func count_vowels(word):
    vowels = ["a", "e", "i", "o", "u"]
    count = 0
    for letter in word:
        if letter in vowels:
            count += 1
    return count

func main():
    say "banana has " + count_vowels("banana") + " vowels"
    say "rhythm has " + count_vowels("rhythm") + " vowels"
    say "education has " + count_vowels("education") + " vowels"
```

